-- v29.60 — garden_crop_agronomy MASSIV-AUSBAU mit web-recherchierten, quellengestützten Daten.
-- Research-Workflow (9 Agenten, WebSearch/WebFetch) über autoritative CH-Quellen: FiBL, Sativa
-- Rheinau, Bioterra, ProSpecieRara, Agroscope, Strickhof, kantonale Fachstellen + etablierte
-- Mischkultur-Tabellen (Plantura/fryd.app/krautundrueben). Companion-Daten konservativ (nur breit
-- übereinstimmende Paarungen), Quellen + Confidence je Kultur gespeichert. Erweitert Planer-Grounding
-- (gsPPbuildAgronomyRef) UND Saison-Mischkultur (renderSeasonList). Idempotent (ON CONFLICT crop DO NOTHING).
alter table public.garden_crop_agronomy add column if not exists source text;
alter table public.garden_crop_agronomy add column if not exists confidence text;

on conflict (crop) do nothing;
